from lib import *
S = SS('g17')
def tail(lines, sub):
    i = [k for k, l in enumerate(lines) if sub in l][0]
    return lines[i:]
L2 = tail(S(2), '函数头')
steps = [
    step("泛型函数 Show[T any] 与 Sum[T int|int32|float64|MyInt] 被不同类型实例化后,用 go tool nm 看二进制里的函数符号:Show 有 7 个——go.shape.*uint8、go.shape.[]int、go.shape.float64、go.shape.int32、go.shape.int、go.shape.map[string]int、go.shape.string;Sum 有 3 个(float64、int32、int);共 10 个。*A 与 *B 共用 go.shape.*uint8,int 与 MyInt 共用 go.shape.int,float64 与 Celsius 共用 go.shape.float64。另有字典符号 14 个(Show 10 个、Sum 4 个),每个真实类型实参一个,如 main..dict.Show[*main.A]、main..dict.Show[main.MyInt]。", t=tl(S(1)), done=lidx(S(1), 'main.Show[go.shape.int]', 'main.Sum[go.shape.int]'), mark=lidx(S(1), 'main.Show[go.shape.*uint8]', '共 10 个函数符号', 'main..dict.Show[*main.A]', 'main..dict.Show[main.MyInt]'), b=bars([['函数符号 Show', 7, '7'], ['函数符号 Sum', 3, '3'], ['字典符号 Show', 10, '10'], ['字典符号 Sum', 4, '4']], 10, done=[0, 1], mark=[2, 3]), kv=KV([['函数符号(机器码)', '按 GC shape:10 个'], ['字典符号', '按真实类型实参:14 个'], ['*A、*B', '共用 go.shape.*uint8'], ['int、MyInt', '共用 go.shape.int'], ['float64、Celsius', '共用 go.shape.float64']], ['函数符号(机器码)'])),
    step("调用点怎么传字典:main.main 里对 Show 的调用,每次先把字典地址放进 R0(MOVD $main..dict.Show[int](SB), R0),再 CALL 对应 shape 的实例:Show(1) 调 main.Show[go.shape.int],Show(MyInt(3)) 也调 main.Show[go.shape.int],但字典是 main..dict.Show[main.MyInt];Show(Celsius(1.5)) 调 go.shape.float64;Show(&A) 调 go.shape.*uint8。函数头对比:泛型实例 main.Show[go.shape.int] 的 args=0x10、size=112,同样函数体的非泛型 ShowInt 是 args=0x8、size=96——多出的 8 字节参数就是字典指针。", t=tl(S(2)), done=lidx(S(2), 'dict.Show[int](SB)', 'dict.Show[float64](SB)'), mark=lidx(S(2), 'dict.Show[main.MyInt](SB)', 'Show[go.shape.int] STEXT', 'ShowInt STEXT'), kv=KV([['调用点', '先传字典地址(R0),再 CALL shape 实例'], ['Show(MyInt(3))', 'CALL main.Show[go.shape.int],字典 dict.Show[main.MyInt]'], ['Show[go.shape.int] 的 args', '0x10(含字典指针)'], ['非泛型 ShowInt 的 args', '0x8']], ['Show(MyInt(3))'])),
    step("调用成本(1000 个元素,7 轮取中位数):具体类型求和 SumInt 305.59 ns/op;泛型 SumGeneric[int] 314.15 ns/op——相同;约束里调用方法:直接调用方法的 TotalDirect([]Foo) 307.96 ns/op,泛型 TotalGeneric[Foo] 909.62 ns/op、TotalGeneric[*PFoo] 938.29 ns/op(约 3 倍);接口切片 TotalIface([]Valer) 2024.07 ns/op。", t=tl(S(3)), done=lidx(S(3), 'SumInt', 'SumGeneric', 'TotalDirect'), mark=lidx(S(3), 'TotalGeneric[Foo]', 'TotalGeneric[*PFoo]', 'TotalIface'), b=bars([['SumInt', 305.59, '306'], ['SumGeneric[int]', 314.15, '314'], ['TotalDirect', 307.96, '308'], ['TotalGeneric[Foo]', 909.62, '910'], ['TotalGeneric[*PFoo]', 938.29, '938'], ['TotalIface', 2024.07, '2024']], 2024.07, done=[0, 1, 2], mark=[3, 4, 5]), kv=KV([['泛型求和 vs 具体求和', '314 vs 306 ns/op,相同'], ['约束里的方法调用', '910 ns/op vs 直接调用 308 ns/op(约 3 倍)'], ['接口切片', '2024 ns/op']], ['约束里的方法调用'])),
    step("二进制体积随实例化数量变化(同一个泛型函数 Work 打印 %v 与 %T):1 种值类型 2430162 字节、1 个函数符号;4 种不同大小的值类型 2430690 字节、4 个符号;16 种 2465858 字节、16 个符号;16 种指向不同结构体的指针类型 2448162 字节、只有 1 个符号。", t=tl(S(4)), done=lidx(S(4), '1 种值类型', '4 种不同大小'), mark=lidx(S(4), '16 种不同大小', '16 种指针类型'), b=bars([['1 种值类型', 2430162, '2430162'], ['4 种值类型', 2430690, '2430690'], ['16 种值类型', 2465858, '2465858'], ['16 种指针类型', 2448162, '2448162']], 2465858, done=[0, 1], mark=[2, 3]), kv=KV([['函数符号数', '1 / 4 / 16 种值类型:1 / 4 / 16 个'], ['16 种指针类型', '只有 1 个函数符号'], ['体积', '16 种值类型比 1 种多约 35 KB']], ['16 种指针类型'])),
]
A = mkartg('g17', 17, 'Go,泛型,GC shape,字典,实现,真实验证,动画演示',
    '在 Go 1.27.1 里用 go tool nm 与汇编验证泛型的实现:按 GC shape 生成机器码(int 与 MyInt 共用 go.shape.int,所有指针类型共用 go.shape.*uint8),每个真实类型实参一个字典,调用点把字典地址作为额外参数传进去;泛型求和与具体求和一样快(约 306 ns),约束里调用方法约慢 3 倍;16 种不同大小的值类型的实例化让二进制多约 35 KB,16 种指针类型只多一个函数。',
    'Go 的泛型既不是 C++ 那样每个类型一份代码,也不是 Java 那样完全擦除。它按“GC shape”分组生成机器码,再用一个字典传递真实类型信息。这篇用符号表与汇编验证这个设计,并量出它对运行速度和二进制体积的影响。',
    [('10 个函数符号', 'Show 与 Sum 被 13 个不同类型实参(含 *A、*B)实例化,但机器码只有 10 份:按 GC shape'), ('args=0x10', '泛型实例比同样函数体的非泛型函数多 8 字节参数:字典指针'), ('3 倍', '在泛型函数里调用约束的方法,比直接调用慢(910 ns vs 308 ns / 1000 次)')],
    [('按 GC shape 生成代码', '<p>符号表里的 <code>go.shape.int</code>、<code>go.shape.*uint8</code> 就是 GC shape:内存布局与 GC 看法相同的类型共用一份机器码。<code>MyInt</code> 的底层类型是 <code>int</code>,所以与 <code>int</code> 共用;所有指针类型共用 <code>*uint8</code> 这一份。这就是为什么 16 种指针类型只生成了一个函数。</p>'),
     ('字典与调用约定', '<p>共用机器码的代价是:函数体不知道自己具体是哪个类型,于是每个实例化多带一个<b>字典</b>参数。调用点用 <code>MOVD $main..dict.Show[main.MyInt](SB), R0</code> 先传字典的地址,再调用 shape 实例。<code>Show[go.shape.int]</code> 的参数大小比同样函数体的非泛型函数多 8 字节(<code>args=0x10</code> 对 <code>0x8</code>),吻合“多一个指针参数”。字典里具体放了什么(类型描述符、子字典、方法表),我没有解析。</p>'),
     ('速度', '<p>两种情形要分开看。<b>不涉及方法调用</b>时(求和),泛型与手写具体类型一样快;<b>要调用约束里的方法</b>时,实例化后的代码要通过字典找到方法再间接调用,实测约 3 倍慢于直接调用(但仍快于接口切片的 2024 ns)。注意这是 <code>//go:noinline</code> 函数上的微基准,内联后编译器可能做得更好,本文没有测。</p>'),
     ('体积', '<p>shape 不同的类型才多一份机器码。16 种不同大小的值类型生成 16 个函数符号,二进制比 1 种时多约 35 KB;16 种指针类型只有 1 个符号,体积只多了字典与类型信息。所以大量用指针类型实例化泛型不会让代码膨胀。</p>')],
    steps,
    [ENV_G + '。符号来自 go tool nm 的 T 类型符号(代码)与名字含 main..dict. 的符号;汇编来自 go build -gcflags=-S;基准测试每个变体 7 轮取中位数;体积是 go build 默认选项下的可执行文件大小',
     '没有验证:字典的内部结构与子字典(没有解析)、泛型方法在接口值里的调用成本、内联与 PGO 对泛型调用的影响、amd64 上的符号与耗时、泛型类型(不只是泛型函数)的方法实例化、Go 版本演进里实现策略的变化'],
    '泛型的实现')
